def fixture_root_randomness(stage, seed_sha256, context, index):
    count = 2 if stage == "excluded-canary" else STAGE_COUNTS[stage]
    # The four reordered distinct-transform roots require no unneeded census.
    values = FROZEN_SEED_COMMITMENTS[seed_sha256][stage]
    offset = index if len(values) == 4 else CONTEXTS.index(context) * count + index
    row = values[offset]
    return PreparedRootRandomness(stage, context, index, seed_sha256, row[:17], row[17])


def fixture_seed_census(stage, seed_sha256):
    count = 2 if stage == "excluded-canary" else STAGE_COUNTS[stage]
    return tuple(
        fixture_root_randomness(stage, seed_sha256, context, index)
        for context in CONTEXTS for index in range(count)
    )
